function freshPlayers(formation){return formPositions(formation).map((p,i)=>({...p,num:i+1,name:i===0?'Qapıçı':`Oyunçu ${i+1}`,role:i===0?'GK':i<=4?'DEF':i<=8?'MID':'ATT'}))}
