async function req(route,timeout=7500){const c=new AbortController();const timer=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(route,{signal:c.signal,headers:{Accept:'application/json'}});if(!r.ok)throw Error(`HTTP ${r.status}`);return await r.json()}finally{clearTimeout(timer)}}
function localSearch(q,kind='all'){q=norm(q);const terms=q.split(' ').filter(Boolean);if(!terms.length)return CAT.filter(x=>kind==='all'||x.kind===kind).slice(0,75);return CAT.filter(x=>(kind==='all'||x.kind===kind)&&terms.every(t=>norm(x.name).includes(t)||norm((x.clubs||[]).join(' ')).includes(t)||norm((x.coached||[]).join(' ')).includes(t)||norm(x.country||'').includes(t))).sort((a,b)=>Number(norm(b.name)===q)-Number(norm(a.name)===q)||a.name.localeCompare(b.name)).slice(0,70)}
function toast(msg){const e=document.getElementById('toast');if(e){e.textContent=msg;e.classList.remove('hide');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.add('hide'),3300)}}
function title(k,title,desc='',right=''){return `<div class="heading"><div><span class="eyebrow">${esc(k)}</span><h1>${esc(title)}</h1>${desc?`<p class="subtitle">${esc(desc)}</p>`:''}</div>${right}</div>`}
function initials(s){return String(s||'?').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function safeImg(s){try{const u=new URL(s);return u.protocol==='https:'&&['commons.wikimedia.org','upload.wikimedia.org','a.espncdn.com','cdn.espn.com','www.openligadb.de','openligadb.de','r2.thesportsdb.com','www.thesportsdb.com','cdn.thesportsdb.com'].includes(u.hostname)?u.href:''}catch{return ''}}
const brokenPhotos=new Set();const photoFallbackAttempted=new Set();
function photoFor(p){const qid=p.wikidataId||p.qid||(p.id.startsWith('Q')?p.id:'');for(const src of [st.photos[p.id],window.ML_FEATURED?.[qid],p.image]){const url=safeImg(src);if(url&&!brokenPhotos.has(url))return url}return ''}
function pic(p,large=false){let url=photoFor(p),club=p.kind==='teams';return `<span class="avatar ${club?'club':''} ${large?'big':''}" title="${esc(p.name)}">${esc(initials(p.name))}${url?`<img src="${esc(url)}" alt="${esc(p.name)}" data-media-id="${esc(p.id)}" loading="lazy" onerror="this.remove()">`:''}</span>`}
function entity(p){return `<button class="entity" data-id="${esc(p.id)}">${pic(p)}<span class="grow"><span class="name">${esc(p.name)}</span><small>${esc(p.description||p.position||p.country||p.kind)}</small></span><span style="color:#89a1b8">›</span></button>`}
function grid(items){return `<div class="grid cards">${items.map(entity).join('')}</div>`}
function banner(text,kind='warn'){return `<div class="notice ${kind}">${esc(text)}</div>`}
function loading(){return '<div class="panel pad"><span class="loader"></span> Məlumat yoxlanılır…</div>'}
